    for (const resource of NUMERIC_RESOURCES) {
      let previous = -1;
      for (const plan of PLAN_ORDER) {
        const limit = getLimit(plan, resource);
        expect(limit).toBeGreaterThanOrEqual(previous);
        previous = limit;
      }
