/**
 * Private helpers that resolve the page a notification or search hit points
 * at.
 *
 * The App Router serves issues at `/[orgSlug]/projects/[projectSlug]/issues/
 * [issueNumber]`, so a link has to be built from slugs and the issue number,
 * never from ULIDs. The shapes themselves live in `@/lib/url`; this module
 * only loads the rows those helpers need. A subject that no longer resolves
 * falls back to the organization's dashboard rather than to a dead link.
 */
import { issuePath, orgPath, projectPath, settingsPath } from "@/lib/url";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import type { CommentId, IssueId, OrgId, ProjectId } from "@/types/common";

const SITE_ROOT = "/";

async function orgSlugFor(orgId: OrgId): Promise<string | null> {
  const org = await orgRepo.findOrgById(orgId);
  return org?.slug ?? null;
}

/** The issue's detail page inside its project. */
export async function issueHref(orgId: OrgId, issueId: IssueId): Promise<string> {
  const orgSlug = await orgSlugFor(orgId);
  if (orgSlug === null) return SITE_ROOT;

  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (!issue) return orgPath(orgSlug);

  const project = await projectRepo.findProjectById(orgId, issue.projectId);
  if (!project) return orgPath(orgSlug);

  return issuePath(orgSlug, project.slug, issue.number);
}

/** Comments have no page of their own; they live on their issue's page. */
export async function commentHref(
  orgId: OrgId,
  commentId: CommentId,
): Promise<string> {
  const comment = await commentRepo.findCommentById(orgId, commentId);
  if (!comment) {
    const orgSlug = await orgSlugFor(orgId);
    return orgSlug === null ? SITE_ROOT : orgPath(orgSlug);
  }
  return issueHref(orgId, comment.issueId);
}

export async function projectHref(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<string> {
  const orgSlug = await orgSlugFor(orgId);
  if (orgSlug === null) return SITE_ROOT;

  const project = await projectRepo.findProjectById(orgId, projectId);
  if (!project) return orgPath(orgSlug);

  return projectPath(orgSlug, project.slug);
}

/** One section of the organization settings, e.g. `members` or `billing`. */
export async function settingsHref(
  orgId: OrgId,
  section: string,
): Promise<string> {
  const orgSlug = await orgSlugFor(orgId);
  return orgSlug === null ? SITE_ROOT : settingsPath(orgSlug, section);
}

