import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);

import { emit } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as invitationService from "@/server/services/invitation-service";
import * as webhookService from "@/server/services/webhook-service";
import * as attachmentService from "@/server/services/attachment-service";
import * as searchService from "@/server/services/search-service";
import * as usageService from "@/server/services/usage-service";
import * as orgService from "@/server/services/organization-service";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { registerEventHandlers } from "@/server/services/event-registry";
import { buildDigest } from "@/server/services/digest-service";
import { runUsageRollupJob } from "@/server/jobs/usage-rollup-job";
import {
  listNotifications,
  markAllRead,
  markRead,
  notify,
  updatePreference,
} from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
import type { Tenant } from "./server/_support/fixtures";
import type { UserId } from "@/types/common";
import type { NotificationKind } from "@/types/notification";

let cleanup: () => void;
let t: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
  t = await createTenant("verify", "growth");
});
afterAll(() => cleanup());

async function inbox(tenant: Tenant, role: keyof Tenant["actors"], kind?: NotificationKind[]) {
  const items = [];
  let cursor: string | null = null;
  for (;;) {
    const page = await listNotifications(tenant.actors[role], {
      orgId: tenant.org.id,
      recipientId: tenant.userIds[role],
      unreadOnly: false,
      kind,
      limit: 3,
      cursor,
    });
    items.push(...page.items);
    if (!page.nextCursor) break;
    cursor = page.nextCursor;
  }
  return items;
}

describe("verify", () => {
  it("personal inbox", async () => {
    await expect(
      listNotifications(t.actors.owner, {
        orgId: t.org.id, recipientId: t.userIds.admin, unreadOnly: false, limit: 25, cursor: null,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    const [row] = await notify(t.org.id, "member_joined", [t.userIds.admin], {
      title: "x", body: "y", href: "/z", actorId: null,
    });
    await expect(markRead(t.actors.owner, { orgId: t.org.id, notificationId: row!.id })).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(markRead(t.actors.admin, { orgId: t.org.id, notificationId: row!.id })).resolves.toMatchObject({ id: row!.id });
    await expect(updatePreference(t.actors.owner, { orgId: t.org.id, userId: t.userIds.admin, kind: "issue_assigned", inApp: false, email: false, digestOnly: false })).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(updatePreference(t.actors.viewer, { orgId: t.org.id, userId: t.userIds.viewer, kind: "digest_ready", inApp: true, email: false, digestOnly: false })).resolves.toBeTruthy();
  });

  it("mark all read is own", async () => {
    const tt = await createTenant("verify-mar", "growth");
    await notify(tt.org.id, "member_joined", [tt.userIds.admin, tt.userIds.viewer], { title: "a", body: "b", href: "/c", actorId: null });
    await notify(tt.org.id, "member_joined", [tt.userIds.admin], { title: "a", body: "b", href: "/c", actorId: null });
    expect(await markAllRead(tt.actors.admin, tt.org.id)).toBe(2);
    const viewer = await listNotifications(tt.actors.viewer, { orgId: tt.org.id, recipientId: tt.userIds.viewer, unreadOnly: true, limit: 25, cursor: null });
    expect(viewer.items).toHaveLength(1);
  });

  it("links + assignment at creation + status change", async () => {
    const tt = await createTenant("verify-links", "growth");
    const issue = await issueService.createIssue(tt.actors.member, issueInput(tt.org.id, tt.project.id, { title: "Linky issue", assigneeId: tt.userIds.admin }));
    const assigned = await inbox(tt, "admin", ["issue_assigned"]);
    expect(assigned).toHaveLength(1);
    expect(assigned[0]!.href).toBe(`/verify-links/projects/platform/issues/${issue.number}`);

    // self-assigned at creation: nothing
    await issueService.createIssue(tt.actors.member, issueInput(tt.org.id, tt.project.id, { title: "Self", assigneeId: tt.userIds.member }));
    expect(await inbox(tt, "member", ["issue_assigned"])).toHaveLength(0);

    await issueService.changeIssueStatus(tt.actors.member, { orgId: tt.org.id, issueId: issue.id, status: "in_progress" });
    await issueService.moveIssue(tt.actors.owner, { orgId: tt.org.id, issueId: issue.id, toStatus: "done", toIndex: 0 } as never);
    await issueService.changeIssueStatus(tt.actors.admin, { orgId: tt.org.id, issueId: issue.id, status: "todo" });
    const status = await inbox(tt, "admin", ["issue_status_changed"]);
    expect(status).toHaveLength(2);
    expect(status[0]!.href).toBe(`/verify-links/projects/platform/issues/${issue.number}`);

    const res = await searchService.search(tt.actors.member, { orgId: tt.org.id, q: "Linky", kinds: [], limit: 25, cursor: null } as never);
    expect(res.items[0]!.href).toBe(`/verify-links/projects/platform/issues/${issue.number}`);
    const proj = await searchService.search(tt.actors.member, { orgId: tt.org.id, q: "Brand", kinds: [], limit: 25, cursor: null } as never);
    expect(proj.items).toHaveLength(0);
  });

  it("member joined goes to owner", async () => {
    const owner = await userRepo.insertUser({ email: "o@vj.test", name: "O", passwordHash: "x" });
    const org = await orgService.createOrganization(owner.id, { name: "VJ", slug: "vj", plan: "growth" } as never);
    const joiner = await userRepo.insertUser({ email: "j@vj.test", name: "J", passwordHash: "x" });
    await emit("member.joined", { orgId: org.id, actorId: joiner.id, occurredAt: new Date().toISOString() as never, memberId: "m" as never, userId: joiner.id, role: "member" });
    const ownerActor = { userId: owner.id, orgId: org.id, role: "owner" as const };
    const page = await listNotifications(ownerActor, { orgId: org.id, recipientId: owner.id, unreadOnly: false, limit: 25, cursor: null });
    expect(page.items).toHaveLength(1);
    expect(page.items[0]!.href).toBe("/vj/settings/members");
    const jp = await listNotifications({ userId: joiner.id, orgId: org.id, role: "member" }, { orgId: org.id, recipientId: joiner.id, unreadOnly: false, limit: 25, cursor: null });
    expect(jp.items).toHaveLength(0);
  });

  it("plan limits", async () => {
    const tt = await createTenant("verify-free", "free");
    const mkProject = (actor = tt.actors.member) => projectService.createProject(actor, {
      orgId: tt.org.id, name: "P" + Math.random(), slug: "p", key: "", description: null, visibility: "org", leadId: null, color: "#6366f1", targetDate: null,
    } as never);
    await mkProject();
    await expect(mkProject()).rejects.toThrow();
    await expect(mkProject(tt.actors.owner)).rejects.toThrow();
    let alerts = await inbox(tt, "owner", ["plan_limit_reached"]);
    expect(alerts).toHaveLength(1);
    expect(alerts[0]!.href).toBe("/verify-free/settings/billing");
    await expect(invitationService.inviteMember(tt.actors.admin, { orgId: tt.org.id, email: "x@y.z", role: "member" })).rejects.toThrow();
    alerts = await inbox(tt, "owner", ["plan_limit_reached"]);
    expect(alerts).toHaveLength(2);
    await markRead(tt.actors.owner, { orgId: tt.org.id, notificationId: alerts.find(a => a.title.includes("projects"))!.id });
    await expect(mkProject()).rejects.toThrow();
    alerts = await inbox(tt, "owner", ["plan_limit_reached"]);
    expect(alerts).toHaveLength(3);
    await expect(webhookService.createWebhook(tt.actors.admin, { orgId: tt.org.id, url: "https://x.y", events: [] } as never)).rejects.toThrow();
    await usageRepo.incrementUsage(tt.org.id, { storageMbUsed: 100 });
    const issue = await issueService.createIssue(tt.actors.member, issueInput(tt.org.id, tt.project.id));
    await expect(attachmentService.addAttachment(tt.actors.member, { orgId: tt.org.id, issueId: issue.id, fileName: "a", contentType: "a/b", sizeBytes: 5, storageKey: "k" } as never)).rejects.toThrow();
    alerts = await inbox(tt, "owner", ["plan_limit_reached"]);
    expect(alerts.length).toBe(4);
    console.log(alerts.map(a => a.title));

    const before = (await inbox(tt, "owner", ["plan_limit_reached"])).length;
    await markAllRead(tt.actors.owner, tt.org.id);
    await usageService.recomputeUsage(tt.org.id);
    await runUsageRollupJob(new Date());
    expect((await inbox(tt, "owner", ["plan_limit_reached"])).length).toBe(before);
  });

  it("in-app off hides and paging", async () => {
    const tt = await createTenant("verify-page", "growth");
    await preferenceRepo.upsertPreference({ orgId: tt.org.id, userId: tt.userIds.viewer, kind: "comment_created", inApp: false, email: true, digestOnly: false });
    for (let i = 0; i < 10; i++) {
      await notify(tt.org.id, "member_joined", [tt.userIds.viewer, tt.userIds.admin], { title: `n${i}`, body: "b", href: "/c", actorId: null });
      await notify(tt.org.id, "comment_created", [tt.userIds.viewer], { title: `c${i}`, body: "b", href: "/c", actorId: null });
    }
    const all = await inbox(tt, "viewer");
    expect(all).toHaveLength(10);
    expect(new Set(all.map((n) => n.id)).size).toBe(10);
    const first = await listNotifications(tt.actors.viewer, { orgId: tt.org.id, recipientId: tt.userIds.viewer, unreadOnly: false, limit: 3, cursor: null });
    expect(first.total).toBe(10);
    expect(await notificationRepo.countUnread(tt.org.id, tt.userIds.viewer)).toBe(10);
    const digest = await buildDigest(tt.org.id, tt.userIds.viewer, "2000-01-01T00:00:00.000Z" as never, "2100-01-01T00:00:00.000Z" as never);
    expect(digest?.entries.length).toBe(20);
    void (null as unknown as UserId);
  });
});

